local function requestBody(url,headers)
    local transport=type(request)=="function" and request or (type(http_request)=="function" and http_request)
    if not transport and type(syn)=="table" then transport=syn.request end
    local body
    if transport then
        local result=transport({Url=url,Method="GET",Headers=headers or {}})
        assert(type(result)=="table" and type(result.Body)=="string","Ungültige HTTP-Antwort")
        local status=tonumber(result.StatusCode)
        assert(status and status>=200 and status<300,"HTTP "..tostring(status or "unbekannt"))
        body=result.Body
    else assert(not headers or next(headers)==nil,"Für diesen Anbieter wird ein HTTP-Provider mit Header-Unterstützung benötigt"); body=game:HttpGet(url) end
    assert(type(body)=="string" and #body<8000000,"Ungültige Antwortgröße")
    return body
end
local function requestJSON(url,headers)
    local body=requestBody(url,headers)
    local decoded=Http:JSONDecode(body)
    assert(type(decoded)=="table","Ungültige JSON-Antwort")
    return decoded
end
local function maintainVoiceConnections(fireReady)
    local enumerator=type(getconnections)=="function" and getconnections or (type(get_signal_cons)=="function" and get_signal_cons)
    if not enumerator then return end
    captureVoiceConnections(enumerator)
    for _,entry in ipairs({{VoiceInternal,"StateChanged"},{VoiceInternal,"Participants"},{Voice,"StateChanged"},{Voice,"PlayerMicStateChanged"}}) do
        pcall(function()
            local service=entry[1]; if not service then return end
            local signal=entry[2]=="Participants" and service:GetPropertyChangedSignal("Participants") or service[entry[2]]
            local items=enumerator(signal)
            for i,connection in pairs(items) do
                pcall(function() if i==8 then connection:Enable(); if fireReady then connection:Fire() end else connection:Disable() end end)
            end
        end)
    end
end
local function toggleAntiVC()
    if antiVC.active then stopAntiVC(); notify("Voice-Modus beendet.","Voice"); return end
    if antiVC.loading then return end
    if not Voice or (type(getconnections)~="function" and type(get_signal_cons)~="function") then
        notify("Die benötigten Voice-Funktionen sind hier nicht verfügbar.","Voice"); return
    end
    antiVC.active=true; antiVC.loading=true
    local micReady,micError=pcall(runtime.buildVoiceMic)
    if not micReady then stopAntiVC(); notify("Mikrofon-Steuerung konnte nicht geöffnet werden.","Voice"); warn("ISB Mikrofon: "..tostring(micError)); return end
    antiVC.generation=(antiVC.generation or 0)+1; local generation=antiVC.generation
    local enumerator=type(getconnections)=="function" and getconnections or get_signal_cons
    captureVoiceConnections(enumerator)
    local ok,message=pcall(function() Voice:leaveVoice() end)
    if not ok then stopAntiVC(); notify(tostring(message):sub(1,140),"Voice"); return end
    task.delay(2.3,function()
        if not alive or not antiVC.active or antiVC.generation~=generation then return end
        local joined=pcall(function() Voice:joinVoice() end)
        if not joined then stopAntiVC(); if alive then notify("Voice-Verbindung nicht verfügbar.","Voice"); if page=="Voice" then render() end end; return end
        task.delay(.3,function()
            if not alive or not antiVC.active or antiVC.generation~=generation then return end
            maintainVoiceConnections(true); antiVC.loading=false
            runtime.syncVoiceMic()
            notify("Voice-Verbindung erneuert und Client-Modus gestartet.","Voice")
            if page=="Voice" then render() end
        end)
    end)
end

local function htmlText(text)
    local values={quot='"',apos="'",amp="&",lt="<",gt=">",nbsp=" "}
    return (tostring(text or ""):gsub("<[^>]+>",""):gsub("&([%w#]+);",function(entity)
        if values[entity] then return values[entity] end
        local n=entity:match("^#x(%x+)$")
        local number=n and tonumber(n,16) or tonumber(entity:match("^#(%d+)$"))
        if number then local ok,value=pcall(utf8.char,number); if ok then return value end end
        return "&"..entity..";"
    end)):match("^%s*(.-)%s*$")
end
local function validSlug(value)
    return type(value)=="string" and #value>0 and #value<400 and not value:find("/",1,true) and not value:find("..",1,true)
end
local function normalizeResult(provider,row)
    if type(row)~="table" or type(row.title)~="string" or not validSlug(row.slug) then return nil end
    local gameName=type(row.game)=="table" and (row.game.name or row.game.title) or row.game
    local owner=type(row.creator)=="table" and row.creator.username or row.owner
    return {provider=provider,slug=row.slug,title=row.title:sub(1,180),game=type(gameName)=="string" and gameName:sub(1,100) or "Universal / nicht angegeben",
        owner=type(owner)=="string" and owner:sub(1,80) or "Nicht angegeben",verified=row.verified==true or row.ownerVerified==true or (type(row.creator)=="table" and row.creator.isVerified==true),
        key=row.key==true or row.isKeySystem==true,source=type(row.script)=="string" and row.script or nil,
        image=type(row.image)=="string" and row.image or (type(row.game)=="table" and row.game.imageUrl or nil),
        views=type(row.views)=="number" and row.views or nil,rawId=row.rawId,description=type(row.description)=="string" and htmlText(row.description):sub(1,600) or ""}
end
local function searchRemoteScripts(targetPage)
    local term=scriptSearch.query:match("^%s*(.-)%s*$") or ""
    if (#term>0 and #term<2) or #term>100 then scriptSearch.error="Suchbegriff: 2 bis 100 Zeichen eingeben."; render(); return end
    local provider=scriptSearch.provider
    settings.provider=provider; settings.discovery=scriptSearch.discovery; save()
    if term=="" and scriptSearch.discovery=="Favoriten" then
        scriptSearch.rows={}; scriptSearch.error=nil; scriptSearch.loaded=true; scriptSearch.loading=false; scriptSearch.selected=nil; scriptSearch.source=nil
        scriptSearch.generation=scriptSearch.generation+1; scriptSearch.page=1; scriptSearch.totalPages=1
        for _,entry in pairs(settings.scriptFavorites) do
            if entry.provider==provider and validSlug(entry.slug) then table.insert(scriptSearch.rows,entry) end
        end
        table.sort(scriptSearch.rows,function(a,b) return a.title<b.title end)
        if render then render() end; return
    end
    scriptSearch.generation=scriptSearch.generation+1
    local generation=scriptSearch.generation
    scriptSearch.loading=true; scriptSearch.error=nil; scriptSearch.selected=nil; scriptSearch.source=nil
    if render then render() end
    task.spawn(function()
        local ok,result=pcall(function()
            local rows,total={},1
            if provider=="ScriptBlox" then
                local url=term=="" and ("https://scriptblox.com/api/script/fetch?sortBy="..(scriptSearch.discovery=="Neu" and "updatedAt" or "views").."&order=desc&page="..targetPage.."&max=12") or ("https://scriptblox.com/api/script/search?q="..Http:UrlEncode(term).."&page="..targetPage.."&max=12")
                local data=requestJSON(url)
                assert(type(data.result)=="table" and type(data.result.scripts)=="table",tostring(data.message or "Ungültige ScriptBlox-Antwort"))
                for _,row in ipairs(data.result.scripts) do local normalized=normalizeResult(provider,row); if normalized then table.insert(rows,normalized) end end
                total=tonumber(data.result.totalPages) or 1
            else
                local url=term=="" and (scriptSearch.discovery=="Neu" and "https://roscripts.io/new" or "https://roscripts.io/trending") or ("https://roscripts.io/search?q="..Http:UrlEncode(term))
                local html=requestBody(url)
                for article in html:gmatch("<article(.-)</article>") do
                    local slug=article:match('href="/s/([^"]+)"')
                    local name=article:match("<h3[^>]*>(.-)</h3>")
                    local rawId=article:match("https://script%.roscripts%.io/([%w]+)")
                    if slug and name then
                        local row={slug=htmlText(slug),title=htmlText(name),game=htmlText(article:match('<span[^>]*title="([^"]+)"') or "Universal"),
                            owner=htmlText(article:match('title="@([^"]+)"') or "Nicht angegeben"),rawId=rawId,
                            image=htmlText(article:match('<img[^>]-src="([^"]+)"') or "")}
                        local normalized=normalizeResult(provider,row); if normalized then table.insert(rows,normalized) end
                    end
                end
                assert(#rows>0 or html:find("No scripts",1,true) or html:find("No results",1,true),"RoScripts-Suchformat geändert oder keine lesbare Ergebnisliste")
                total=math.max(1,math.ceil(#rows/12))
                return {allRows=rows,total=total,rows=rows}
            end
            return {rows=rows,total=total}
        end)
        if not alive or generation~=scriptSearch.generation then return end
        scriptSearch.loading=false; scriptSearch.loaded=true
        if ok then
            scriptSearch.page=targetPage; scriptSearch.totalPages=math.max(1,math.min(10000,result.total))
            if provider=="RoScripts" then
                scriptSearch.allRows=result.allRows; scriptSearch.rows={}
                for i=(targetPage-1)*12+1,math.min(targetPage*12,#result.allRows) do table.insert(scriptSearch.rows,result.allRows[i]) end
            else scriptSearch.rows=result.rows; scriptSearch.allRows={} end
        else
            scriptSearch.error=tostring(result):sub(1,200); scriptSearch.rows={}
            logEvent("Script-Suche",provider..": "..scriptSearch.error)
        end
        if page=="Skripte" and render then render() end
    end)
end
local function loadScriptSource(entry)
    scriptSearch.selected=entry; scriptSearch.source=nil; scriptSearch.loading=true; scriptSearch.error=nil
    scriptSearch.generation=scriptSearch.generation+1; local generation=scriptSearch.generation
    render()
    task.spawn(function()
        local ok,source=pcall(function()
            if entry.provider=="ScriptBlox" then
                local data=requestJSON("https://scriptblox.com/api/script/"..Http:UrlEncode(entry.slug))
                local record=data.script or (data.result and data.result.script)
                if type(record)=="table" then return record.script end
                if type(record)=="string" then return record end
                return entry.source
            else
                assert(type(entry.rawId)=="string" and entry.rawId:match("^%w+$"),"Kein lesbarer RoScripts-Loader gefunden")
                return requestBody("https://script.roscripts.io/"..entry.rawId)
            end
        end)
        if not alive or generation~=scriptSearch.generation then return end
        scriptSearch.loading=false
        if ok and type(source)=="string" and source~="" and #source<3000000 and not source:match("^%s*<!") then scriptSearch.source=source
        else scriptSearch.error="Quelltext nicht verfügbar: "..tostring(ok and "Anbieterantwort enthält kein Lua-Script" or source):sub(1,160) end
        if page=="Skripte" then render() end
    end)
end
local function fetchServers(cursor)
    if servers.loading then return end
    servers.loading=true; servers.error=nil; servers.generation=servers.generation+1
    local generation=servers.generation
    task.spawn(function()
        local ok,result=pcall(function()
            local url="https://games.roblox.com/v1/games/"..tostring(game.PlaceId).."/servers/Public?sortOrder="..servers.sort.."&limit=100"
            if cursor then url=url.."&cursor="..Http:UrlEncode(cursor) end
            local data=requestJSON(url); assert(type(data.data)=="table","Serverliste fehlt")
            local rows,seen={},{}
            for _,entry in ipairs(data.data) do
                if type(entry)=="table" and type(entry.id)=="string" and entry.id:match("^[%w%-]+$") and #entry.id<=100
                    and type(entry.playing)=="number" and entry.playing>=0 and entry.playing==entry.playing
                    and type(entry.maxPlayers)=="number" and entry.maxPlayers>0 and entry.maxPlayers==entry.maxPlayers
                    and not seen[entry.id] then
                    seen[entry.id]=true
                    table.insert(rows,{id=entry.id,playing=math.floor(entry.playing),maxPlayers=math.floor(entry.maxPlayers),
                        ping=type(entry.ping)=="number" and entry.ping==entry.ping and entry.ping>=0 and entry.ping<1e7 and math.floor(entry.ping) or nil,
                        fps=type(entry.fps)=="number" and entry.fps==entry.fps and entry.fps>=0 and entry.fps<1e7 and math.floor(entry.fps) or nil})
                end
            end
            return {rows=rows,nextCursor=type(data.nextPageCursor)=="string" and data.nextPageCursor or nil}
        end)
        if not alive or generation~=servers.generation then return end
        servers.loading=false; servers.loaded=true
        if ok then servers.data=result.rows; servers.cursor=cursor; servers.nextCursor=result.nextCursor
        else servers.error=tostring(result):sub(1,160); logEvent("Serverliste",servers.error) end
        if page=="Server" and render then render() end
    end)
end
local function joinServer(id)
    if not Teleport then notify("TeleportService ist nicht verfügbar.","Server"); return end
    if type(id)~="string" or id=="" then notify("Für diesen Server ist keine Job-ID verfügbar.","Server"); return end
