function runtime.bindPress(obj,callback,register)
    obj.Active=true; obj.Selectable=UIS.GamepadEnabled==true
    -- Keep the real input label fixed and animate a separate rendered face.
    local face=make(obj.ClassName,{Name="ButtonFace",Active=false,Selectable=false,AnchorPoint=Vector2.new(.5,.5),Position=UDim2.fromScale(.5,.5),Size=UDim2.fromScale(1,1),ZIndex=obj.ZIndex or 1},obj)
    local faceScale=make("UIScale",{Name="ButtonFaceScale",Scale=1},face)
    round(face,10)
    local controlOutline=make("Frame",{Name="ControlOutline",Active=false,BackgroundTransparency=1,Position=UDim2.fromOffset(2,2),Size=UDim2.new(1,-4,1,-4),ZIndex=obj.ZIndex or 1},face)
    round(controlOutline,8)
    local controlEdge=make("UIStroke",{Name="ControlEdge",ApplyStrokeMode=Enum.ApplyStrokeMode.Border,Color=Color3.fromRGB(176,197,227),Thickness=1,Transparency=.92},controlOutline)
    register(obj:GetPropertyChangedSignal("BackgroundTransparency"),function() controlEdge.Transparency=obj.BackgroundTransparency>=.95 and 1 or .92 end)
    controlEdge.Transparency=obj.BackgroundTransparency>=.95 and 1 or .92
    local properties={"BackgroundColor3","BackgroundTransparency","BorderSizePixel"}
    if obj:IsA("TextLabel") then
        for _,key in ipairs({"Text","Font","TextSize","TextColor3","TextTransparency","TextXAlignment","TextYAlignment","TextWrapped","TextScaled","RichText","TextTruncate"}) do table.insert(properties,key) end
    elseif obj:IsA("ImageLabel") then
        for _,key in ipairs({"Image","ImageColor3","ImageTransparency","ScaleType"}) do table.insert(properties,key) end
    end
    for _,key in ipairs(properties) do
        if obj[key]~=nil then face[key]=obj[key] end
        register(obj:GetPropertyChangedSignal(key),function() face[key]=obj[key] end)
    end
    -- UIGradient affects this label's own paint, not its child face or icons.
    make("UIGradient",{Name="InputOnlyPaint",Transparency=NumberSequence.new(1)},obj)
    local parentCorner=obj:FindFirstChildOfClass("UICorner")
    if parentCorner then
        face:FindFirstChildOfClass("UICorner").CornerRadius=parentCorner.CornerRadius
        round(controlOutline,math.max(0,parentCorner.CornerRadius.Offset-2))
        register(parentCorner:GetPropertyChangedSignal("CornerRadius"),function()
            face:FindFirstChildOfClass("UICorner").CornerRadius=parentCorner.CornerRadius
            round(controlOutline,math.max(0,parentCorner.CornerRadius.Offset-2))
        end)
    end
    -- Animate decoration and contents; the interactive rectangle stays still.
    local glow=make("Frame",{Name="ButtonMotion",Active=false,Selectable=false,BackgroundColor3=C.accent,BackgroundTransparency=1,
        AnchorPoint=Vector2.new(.5,.5),Position=UDim2.fromScale(.5,.5),Size=UDim2.new(1,-8,1,-8),ZIndex=obj.ZIndex or 1},obj)
    round(glow,10)
    -- The outline belongs to the face and sits a full pixel inside it.
    glow.Parent=face; glow.Size=UDim2.new(1,-4,1,-4); glow.ZIndex=(obj.ZIndex or 1)+1
    local edge=make("UIStroke",{Color=C.accent,Thickness=1,Transparency=1},glow)
    local function contents(child)
        if child~=face and child~=glow and child:IsA("GuiObject") and child.Name~="MicHint" then child.Parent=face end
    end
    for _,child in ipairs(obj:GetChildren()) do contents(child) end
    register(obj.ChildAdded,contents)
    register(obj:GetPropertyChangedSignal("ZIndex"),function() face.ZIndex=obj.ZIndex; glow.ZIndex=obj.ZIndex+1 end)
    local hovered,pressed=false,nil
    local fontBase=nil
    local iconScales=setmetatable({},{__mode="k"})
    local function pose(down)
        local enabled=not settings.reducedMotion
        glow.BackgroundColor3=C.accent; edge.Color=C.accent
        local corner=obj:FindFirstChildOfClass("UICorner")
        if corner then
            face:FindFirstChildOfClass("UICorner").CornerRadius=corner.CornerRadius
            glow:FindFirstChildOfClass("UICorner").CornerRadius=UDim.new(corner.CornerRadius.Scale,math.max(0,corner.CornerRadius.Offset-2))
        end
        local navigation=obj.Name:sub(1,3)=="Nav"
        local copying=obj.Name:sub(1,5)=="Copy_"
        local scriptTile=obj.Name=="ScriptTile"
        local height=obj.AbsoluteSize.Y
        if height<=0 then
            height=obj.Size.Y.Offset
            local ancestor=obj.Parent
            while ancestor do
                local ancestorScale=ancestor:FindFirstChildOfClass("UIScale")
                if ancestorScale then height=height*ancestorScale.Scale end
                ancestor=ancestor.Parent
            end
        end
        -- All controls move as one unit. Inner movement fits even flush clipping edges.
        local factor=enabled and (down and .92 or (hovered and (navigation and 1.12 or (copying and 1.08 or .94)) or 1)) or 1
        local lift=enabled and hovered and not down and (navigation and -4 or -math.min(2,height*.02)) or 0
        animate(faceScale,{Scale=factor})
        animate(face,{Position=UDim2.new(.5,0,.5,lift)})
        animate(glow,{BackgroundTransparency=scriptTile and 1 or (down and .78 or (hovered and .86 or 1))})
        animate(edge,{Transparency=hovered and .35 or 1})
        if obj:IsA("TextLabel") and obj.Text~="" then
            fontBase=fontBase or obj.TextSize
            animate(obj,{TextSize=fontBase*(enabled and (hovered and not down and 1.08 or 1) or 1)})
        end
        for _,child in ipairs(face:GetChildren()) do
            if (child:IsA("ImageLabel") or child.Name=="ButtonGlyph") and child.Name~="ScriptThumbnail" then
                local iconScale=iconScales[child]
                if not iconScale then iconScale=make("UIScale",{Name="ButtonIconMotion",Scale=1},child); iconScales[child]=iconScale end
                animate(iconScale,{Scale=enabled and (down and .94 or (hovered and (copying and 1 or (child.Name=="ButtonGlyph" and 1.32 or 1.12)) or 1)) or 1})
            end
        end
    end
    local function clearHover()
        hovered=false; pressed=nil; pose(false)
        if runtime.hoverOwner==obj then runtime.hoverOwner=nil; runtime.clearHover=nil end
    end
    local function enter()
        if runtime.hoverOwner~=obj then playUISound("hover") end
        if runtime.hoverOwner~=obj and runtime.clearHover then runtime.clearHover() end
        runtime.hoverOwner=obj; runtime.clearHover=clearHover
        hovered=true; pose(pressed~=nil)
    end
    register(obj.MouseEnter,enter); register(face.MouseEnter,enter)
    local function begin(input)
        if input.UserInputType==Enum.UserInputType.MouseButton1 or input.UserInputType==Enum.UserInputType.Touch then pressed=input; pose(true) end
        if (input.KeyCode==Enum.KeyCode.Return or input.KeyCode==Enum.KeyCode.Space or input.KeyCode==Enum.KeyCode.ButtonA)
            and runtime.guiService and runtime.guiService.SelectedObject==obj then callback() end
    end
    local function finish(input)
        if pressed and (input==pressed or input.UserInputType==Enum.UserInputType.MouseButton1) then pressed=nil; pose(false); callback() end
    end
    register(obj.InputBegan,begin); register(face.InputBegan,begin)
    register(obj.InputEnded,finish); register(face.InputEnded,finish)
    -- Root hit geometry never moves; leaving it always clears the hover.
    register(obj.MouseLeave,clearHover)
    register(obj:GetPropertyChangedSignal("Visible"),function() if not obj.Visible then clearHover() end end)
    register(UIS.WindowFocusReleased,clearHover)

end
