local function remember(h)
    if h and not originals[h] then
        originals[h] = {WalkSpeed = h.WalkSpeed, JumpPower = h.JumpPower, JumpHeight = h.JumpHeight}
    end
end
local function applyMovement()
    local h = humanoid()
    if not h or not (state.speed or state.jump) then return end
    remember(h)
    if runtime.movementHumanoid~=h then
        for _,connection in ipairs(runtime.movementConnections or {}) do connection:Disconnect() end
        runtime.movementConnections={}; runtime.movementHumanoid=h
        for _,property in ipairs({"WalkSpeed","JumpPower","JumpHeight","UseJumpPower"}) do
            table.insert(runtime.movementConnections,h:GetPropertyChangedSignal(property):Connect(function()
                if not alive or runtime.movementPending or not (state.speed or state.jump) then return end
                runtime.movementPending=true
                task.defer(function()
                    if alive and humanoid()==h then applyMovement() end
                end)
            end))
        end
    end
    if state.speed then
        if not originals[h].speedOwned then originals[h].WalkSpeed=h.WalkSpeed end
        originals[h].speedOwned=true; if h.WalkSpeed~=state.speedValue then h.WalkSpeed = state.speedValue end
    end
    if state.jump then
        if not originals[h].jumpOwned then originals[h].JumpPower=h.JumpPower; originals[h].JumpHeight=h.JumpHeight end
        originals[h].jumpOwned=true
        if h.UseJumpPower then h.JumpPower = state.jumpValue
        else local height=state.jumpValue * state.jumpValue / (2 * math.max(workspace.Gravity, 1)); if h.JumpHeight~=height then h.JumpHeight=height end end
    end
end
