local function playQueue(index)
    if #musicQueue==0 then return end
    queueIndex=(index-1)%#musicQueue+1
    sound:Stop(); sound.SoundId="rbxassetid://"..musicQueue[queueIndex]; sound:Play()
    runtime.musicInfo=runtime.musicInfo or {}
    local id=musicQueue[queueIndex]
    if Marketplace and not runtime.musicInfo[id] then
        runtime.musicInfo[id]={name="Audio "..id,artist="Roblox Audio"}
        task.spawn(function()
            local ok,info=pcall(function()
                if type(Marketplace.GetProductInfoAsync)=="function" then return Marketplace:GetProductInfoAsync(tonumber(id),Enum.InfoType.Asset) end
                return Marketplace:GetProductInfo(tonumber(id),Enum.InfoType.Asset)
            end)
            if alive and ok and type(info)=="table" then runtime.musicInfo[id]={name=tostring(info.Name or "Audio "..id),artist=type(info.Creator)=="table" and tostring(info.Creator.Name or "Roblox Audio") or "Roblox Audio"} end
        end)
    end
end
