function runtime.characterParts()
    local char=player.Character
    if runtime.partsCharacter~=char then
        if runtime.partsConnection then runtime.partsConnection:Disconnect(); runtime.partsConnection=nil end
        runtime.partsCharacter=char; runtime.parts={}
        if char then
            for _,obj in ipairs(char:GetDescendants()) do if obj:IsA("BasePart") then table.insert(runtime.parts,obj) end end
            runtime.partsConnection=connect(char.DescendantAdded,function(obj) if obj:IsA("BasePart") then table.insert(runtime.parts,obj) end end)
        end
    end
    return runtime.parts or {}
end
function runtime.disableCharacterCollisions()
    for _,part in ipairs(runtime.characterParts()) do
        if part.Parent then
            if collisions[part]==nil then collisions[part]=part.CanCollide end
            if part.CanCollide then part.CanCollide=false end
        end
    end
end
function runtime.stopRoleplay()
    pcall(function() Run:UnbindFromRenderStep("ISBRoleplayFollow") end)
    local owned=runtime.roleplay; runtime.roleplay=nil
    if not owned then return end
    if owned.track then pcall(function() owned.track:Stop(.15); owned.track:Destroy() end) end
    if owned.animation then owned.animation:Destroy() end
    if owned.seatedCaptured then pcall(function() owned.h:SetStateEnabled(Enum.HumanoidStateType.Seated,owned.seatedEnabled) end) end
    if owned.h and owned.h.Parent then
        owned.h.PlatformStand=owned.platformStand; owned.h.AutoRotate=owned.autoRotate
        if not owned.platformStand then owned.h:ChangeState(Enum.HumanoidStateType.GettingUp) end
    end
    local r=root(); if r then r.AssemblyLinearVelocity=Vector3.zero end
    if not state.noclip then restoreCollisions() end
    for _,item in ipairs(runtime.quickActionButtons or {}) do if item.button.Parent then item.button.BackgroundColor3=C.card end end
    if runtime.quickState then runtime.quickState.Text="Bereit · Aktion auswählen" end
end
function runtime.roleplayPart(target,mode)
    local char=target and target.Character
    if not char then return end
    if mode.part=="Head" then return char:FindFirstChild("Head") end
    return char:FindFirstChild("UpperTorso") or char:FindFirstChild("Torso") or char:FindFirstChild("HumanoidRootPart")
end
function runtime.nearestRoleplayTarget(mode)
    local own=root(); if not own then return end
    local chosen,closest=nil,math.huge
    for _,other in ipairs(Players:GetPlayers()) do if other~=player and other.Parent then
        local part=runtime.roleplayPart(other,mode); local h=other.Character and other.Character:FindFirstChildOfClass("Humanoid")
        if part and h and h.Health>0 then
            local distance=(own.Position-part.Position).Magnitude
            if distance<closest or (distance==closest and chosen and other.UserId<chosen.UserId) then chosen=other; closest=distance end
        end
    end end
    return chosen
end
function runtime.roleplayFrame(owned,part,dt,rendered)
    local frame=part.CFrame
    if rendered then
        local ok,value=pcall(function() return part:GetRenderCFrame() end)
        if ok and value then frame=value end
    end
    local position=frame.Position or part.Position
    local mode=owned.mode
    if mode.id=="head" then
        -- Keep the character upright. Looking down rotates the complete rig
        -- onto its stomach instead of placing the seated pose on the head.
        local forward=Vector3.new(frame.LookVector.X,0,frame.LookVector.Z)
        if forward.Magnitude<.001 then forward=Vector3.new(0,0,-1) end
        local target=position+Vector3.new(0,1,0)
        return CFrame.lookAt(target,target+forward.Unit,Vector3.new(0,1,0))
    end
    if mode.id=="piggy" or mode.id=="piggy2" then
        local target=position-frame.LookVector*1.1+Vector3.new(0,.2,0)
        return CFrame.new(target,target+frame.LookVector)
    end
    local offset=mode.offset
    if mode.id=="hug" then
        owned.oscTime=(owned.oscTime or 0)+(dt or 1/60)*10
        local target=frame*CFrame.new(0,.05,-1.35-math.sin(owned.oscTime)*.04)*CFrame.Angles(0,math.pi,0)
        return target
    end
    return frame*CFrame.new(offset[1],offset[2],offset[3])*CFrame.Angles(0,mode.rotation or 0,0)
end
function runtime.startRoleplay(mode)
    local target=runtime.quickTarget or runtime.nearestRoleplayTarget(mode)
    local part=runtime.roleplayPart(target,mode)
    local h,r=humanoid(),root()
    local targetH=target and target.Character and target.Character:FindFirstChildOfClass("Humanoid")
    if not target or target==player or not target.Parent or not part or not h or not r or h.Health<=0 or not targetH or targetH.Health<=0 then notify("Wähle einen verfügbaren Spieler als Ziel.","Roleplay"); return end
    runtime.stopRoleplay(); runtime.stopEmote()
    if state.fly then state.fly=false; stopFly() end
    local owned={target=target,mode=mode,h=h,root=r,platformStand=h.PlatformStand,autoRotate=h.AutoRotate}
    pcall(function() owned.seatedEnabled=h:GetStateEnabled(Enum.HumanoidStateType.Seated); owned.seatedCaptured=true; h:SetStateEnabled(Enum.HumanoidStateType.Seated,false) end)
    runtime.roleplay=owned; h.PlatformStand=true; h.AutoRotate=false
    Run:BindToRenderStep("ISBRoleplayFollow",Enum.RenderPriority.Last.Value+1,function()
        if not alive or runtime.roleplay~=owned then return end
        local part=runtime.roleplayPart(owned.target,owned.mode)
        if not owned.target.Parent or not part or root()~=owned.root then runtime.stopRoleplay(); return end
        owned.root.CFrame=runtime.roleplayFrame(owned,part,0,true)
    end)
    for _,item in ipairs(runtime.quickActionButtons or {}) do if item.button.Parent then item.button.BackgroundColor3=item.mode==mode and C.accent:Lerp(C.panel,.7) or C.card end end
    local animator=h:FindFirstChildOfClass("Animator")
    if animator and h.RigType~=Enum.HumanoidRigType.R6 then
        local resolved="rbxassetid://"..mode.animation
        -- Packaged Animation assets can have a different asset ID from the clip ID.
        pcall(function()
            local objects=game:GetObjects(resolved)
            for _,asset in ipairs(objects) do
                local clip=asset:IsA("Animation") and asset or asset:FindFirstChildOfClass("Animation")
                if clip and clip.AnimationId~="" then resolved=clip.AnimationId end
                asset:Destroy()
            end
        end)
        if runtime.roleplay~=owned then return end
        owned.animation=make("Animation",{Name="ISBRoleplayAnimation",AnimationId=resolved})
        local ok,track=pcall(function() return animator:LoadAnimation(owned.animation) end)
        if ok and track then
            owned.track=track; track.Looped=true; track.Priority=Enum.AnimationPriority.Action4
            pcall(function() track:Play(.05,1,1) end)
            if mode.id=="head" then
                task.delay(2,function() if runtime.roleplay==owned then owned.frozenPose=true; pcall(function() track:AdjustSpeed(0); track.TimePosition=2 end) end end)
            end
        else notify("Position aktiv; die Animation ist in diesem Spiel nicht verfügbar.","Roleplay") end
    end
    if runtime.quickState then runtime.quickState.Text=mode.name.." · "..target.DisplayName end
    if runtime.quickTargetButton and not runtime.quickTarget then runtime.quickTargetButton.Text="Automatisch · "..target.DisplayName end
end
