function runtime.markerColor(friend,staff)
    if staff then return Color3.fromRGB(234,71,71) end
    if friend then return Color3.fromRGB(52,144,255) end
    -- Blue stays reserved for friends when the interface accent is blue.
    return settings.theme=="Blue" and Color3.fromRGB(255,190,82) or C.accent
end
