if Run.PostSimulation then connect(Run.PostSimulation,function()
    runtime.finishExtraJump()
    local owned=runtime.roleplay
    if not owned or not owned.root.Parent then return end
    local part=runtime.roleplayPart(owned.target,owned.mode)
    if part and owned.target.Parent then
        owned.root.CFrame=runtime.roleplayFrame(owned,part,0)
        owned.root.AssemblyLinearVelocity=part.AssemblyLinearVelocity or Vector3.zero
        owned.root.AssemblyAngularVelocity=part.AssemblyAngularVelocity or Vector3.zero
    end
end) end
connect(Run.PreSimulation,function(dt)
    applyMovement()
    if runtime.roleplay then
        local owned=runtime.roleplay; local r=root(); local part=runtime.roleplayPart(owned.target,owned.mode)
        local targetH=owned.target.Character and owned.target.Character:FindFirstChildOfClass("Humanoid")
        if not owned.target.Parent or not part or not r or humanoid()~=owned.h or owned.h.Health<=0 or not targetH or targetH.Health<=0 then runtime.stopRoleplay()
        else
            runtime.disableCharacterCollisions()
            -- Keep our character's replication root. Linking it to another
            -- avatar can prevent that avatar's client from seeing us.
            if owned.track then pcall(function()
                if not owned.track.IsPlaying then owned.track:Play(.05,1,1) end
                if owned.frozenPose then
                    if owned.track.Speed~=0 then owned.track:AdjustSpeed(0) end
                    if math.abs(owned.track.TimePosition-2)>.001 then owned.track.TimePosition=2 end
                end
            end) end
            r.CFrame=runtime.roleplayFrame(owned,part,dt)
            r.AssemblyLinearVelocity=part.AssemblyLinearVelocity or Vector3.zero; r.AssemblyAngularVelocity=part.AssemblyAngularVelocity or Vector3.zero; owned.h.PlatformStand=true; owned.h.AutoRotate=false
            pcall(function() if owned.h:GetState()==Enum.HumanoidStateType.Seated then owned.h:ChangeState(Enum.HumanoidStateType.Physics) end end)
        end
    end
    if runtime.antiVoid then
        local r,h=root(),humanoid()
        if r and h and h.Health>0 and not state.fly then
            if h.FloorMaterial and h.FloorMaterial~=Enum.Material.Air and r.Position.Y>(workspace.FallenPartsDestroyHeight or -500)+100 then runtime.safeGround=r.CFrame end
            if runtime.safeGround and r.Position.Y<(workspace.FallenPartsDestroyHeight or -500)+75 and os.clock()>(runtime.voidCooldown or 0) then
                r.CFrame=runtime.safeGround+Vector3.new(0,5,0); r.AssemblyLinearVelocity=Vector3.zero; runtime.voidCooldown=os.clock()+2
                notify("Zum letzten Bodenpunkt zurückgekehrt.","Anti-Void")
            end
        end
    end
    local camera=workspace.CurrentCamera
    if state.fly and camera and flyObjects[1] and flyObjects[1].Parent then
        local h=humanoid()
        local direction=h and h.MoveDirection or Vector3.zero
        local up=touchVertical
        if not UIS:GetFocusedTextBox() then
            if not UIS.TouchEnabled then
                local forward=(UIS:IsKeyDown(Enum.KeyCode.W) and 1 or 0)-(UIS:IsKeyDown(Enum.KeyCode.S) and 1 or 0)
                local sideways=(UIS:IsKeyDown(Enum.KeyCode.D) and 1 or 0)-(UIS:IsKeyDown(Enum.KeyCode.A) and 1 or 0)
                direction=camera.CFrame.LookVector*forward+camera.CFrame.RightVector*sideways
            end
            if UIS:IsKeyDown(Enum.KeyCode.Space) then up=up+1 end
            if UIS:IsKeyDown(Enum.KeyCode.LeftControl) then up=up-1 end
        else direction=Vector3.zero; up=0 end
        local target=direction+Vector3.new(0,up,0)
        if target.Magnitude>1 then target=target.Unit end
        target=target*runtime.flightLevel().speed
        local step=math.clamp(dt,0,.25)
        local frequency=target.Magnitude>.01 and 8 or 10
        local offset=runtime.flightVelocity-target
        local change=runtime.flightAcceleration+offset*frequency
        local decay=math.exp(-frequency*step)
        runtime.flightVelocity=target+(offset+change*step)*decay
        runtime.flightAcceleration=(runtime.flightAcceleration-change*frequency*step)*decay
        if target.Magnitude<.01 and runtime.flightVelocity.Magnitude<.05 and runtime.flightAcceleration.Magnitude<.1 then runtime.flightVelocity=Vector3.zero; runtime.flightAcceleration=Vector3.zero end
        runtime.updateFlightAnimation(runtime.flightVelocity.Magnitude,runtime.flightLevel().speed)
        flyObjects[1].VectorVelocity=runtime.flightVelocity
        flyObjects[2].CFrame=CFrame.lookAt(Vector3.zero,camera.CFrame.LookVector,camera.CFrame.UpVector)
        if h and h:GetState()~=Enum.HumanoidStateType.Physics then h:ChangeState(Enum.HumanoidStateType.Physics) end
    end
end)
