        local viewport=workspace.CurrentCamera and workspace.CurrentCamera.ViewportSize.X or 1280
        local width=math.min(540,math.max(260,viewport-24)); local compact=width<500
        local height=compact and 88 or 48
        runtime.flightHud.Size=UDim2.fromOffset(width,height)
        runtime.flightNext.Position=compact and UDim2.fromOffset(14,49) or UDim2.new(1,-284,0,9)
        runtime.flightStyleButton.Position=UDim2.new(1,-196,0,compact and 49 or 9)
        runtime.flightInfo.Size=UDim2.new(1,compact and -28 or -302,0,34)
        runtime.flightInfo.TextSize=12
        runtime.flightStyleMenu.Position=UDim2.new(.5,width/2-220,0,58+height+8)
    end
    flyTouch.Visible=state.fly and UIS.TouchEnabled
    if not state.fly then touchVertical=0 end
    local camera=workspace.CurrentCamera
    if camera and (camera~=lastCamera or camera.ViewportSize~=lastViewport) then
        lastCamera=camera; lastViewport=camera.ViewportSize; fit()
    end
    if state.fov and camera then
        if cameraOriginal[camera]==nil then cameraOriginal[camera]=camera.FieldOfView end
        if camera.FieldOfView~=state.fovValue then camera.FieldOfView=state.fovValue end
    end
    if spectating and camera then
        local h=spectating.Character and spectating.Character:FindFirstChildOfClass("Humanoid")
        if h then
            if not spectateOriginal[camera] then spectateOriginal[camera]={subject=camera.CameraSubject,kind=camera.CameraType} end
            camera.CameraSubject=h
        end
    end
    runtime.inventoryTimer=runtime.inventoryTimer+dt
    if runtime.inventoryTimer>=.5 then runtime.inventoryTimer=0; runtime.updateInventoryClearance() end
    frames=frames+1; fpsTime=fpsTime+dt; visualTimer=visualTimer+dt
    if fpsTime>=1 then
        dockClock.Text=os.date("%H:%M")
        local ok,ping=pcall(function() return player:GetNetworkPing()*1000 end)
        session.fps=math.floor(frames/fpsTime+0.5); runtime.updateFPSLimit(fpsTime); session.ping=ok and math.floor(ping+0.5) or nil
        metrics.Text=string.format('%d / %s Spieler  ·  <font color="%s">%s ms</font>  ·  <font color="%s">%d FPS</font>',#Players:GetPlayers(),tostring(Players.MaxPlayers or "—"),runtime.metricTint(session.ping,"ping"),session.ping and tostring(session.ping) or "--",runtime.metricTint(session.fps,"fps"),session.fps)
        runtime.updateStatusLayout()
        if page=="Start" then updateDashboard() end
        frames=0; fpsTime=0
    end
    if antiVC.active then
        if not runtime.voiceMic or not runtime.voiceMic.Parent then pcall(runtime.buildVoiceMic) end
        runtime.voiceMicSync=(runtime.voiceMicSync or 0)+dt
        if runtime.voiceMicSync>=.1 then runtime.voiceMicSync=0; runtime.syncVoiceMic() end
        runtime.voiceMaintenance=runtime.voiceMaintenance+dt
        if runtime.voiceMaintenance>=3 and not antiVC.loading then runtime.voiceMaintenance=0; maintainVoiceConnections() end
    end
    if visualTimer<0.25 then return end
    visualTimer=0
    local ownRoot=root()
    for _,other in ipairs(Players:GetPlayers()) do
        if other~=player then
            local char=other.Character
            local targetRoot=char and char:FindFirstChild("HumanoidRootPart")
            local friend=settings.friendHighlights and session.friends[other.UserId]
            local staff=settings.staffHighlights and runtime.gameStaff[other]
            local marked=state.esp or friend or staff
            local color=runtime.markerColor(friend,staff)
            if highlights[other] and (not marked or highlights[other].Adornee~=char) then highlights[other]:Destroy(); highlights[other]=nil end
            if marked and char and not highlights[other] then
                highlights[other]=make("Highlight",{Name="ISBHighlight",Adornee=char,FillColor=color,
                    FillTransparency=0.78,OutlineColor=color,OutlineTransparency=0.15,
                    DepthMode=Enum.HighlightDepthMode.AlwaysOnTop},char)
            end
            if highlights[other] then highlights[other].FillColor=color; highlights[other].OutlineColor=color end
            if tags[other] and (not state.names or tags[other].Adornee~=targetRoot) then tags[other]:Destroy(); tags[other]=nil end
            if state.names and targetRoot then
                if not tags[other] then
                    local tag=make("BillboardGui",{Name="ISBNametag",Adornee=targetRoot,AlwaysOnTop=true,
                        Size=UDim2.fromOffset(156,44),StudsOffset=Vector3.new(0,3.5,0)},gui)
                    local shell=make("Frame",{Name="NameCard",Size=UDim2.fromOffset(156,44),BackgroundColor3=C.panel,BackgroundTransparency=.12},tag); round(shell,14); stroke(shell)
                    make("UIScale",{Name="DistanceScale",Scale=1},shell)
                    local badge=make("ImageLabel",{Image="rbxthumb://type=AvatarHeadShot&id="..other.UserId.."&w=150&h=150",Name="Badge",BackgroundColor3=color,Position=UDim2.fromOffset(8,10),Size=UDim2.fromOffset(24,24)},shell); round(badge,14)
                    local name=label(shell,other.DisplayName,14,C.text,UDim2.fromOffset(38,4),UDim2.new(1,-46,0,20)); name.Name="PlayerName"; name.Font=Enum.Font.BuilderSansBold; name.TextTruncate=Enum.TextTruncate.AtEnd
                    local info=label(shell,"",12,C.muted,UDim2.fromOffset(38,24),UDim2.new(1,-46,0,16)); info.Name="PlayerInfo"
                    tags[other]=tag
                end
                local distance=ownRoot and math.floor((ownRoot.Position-targetRoot.Position).Magnitude) or 0
                local shell=tags[other]:FindFirstChild("NameCard")
