    if highlights[other] then highlights[other]:Destroy(); highlights[other]=nil end
    if tags[other] then tags[other]:Destroy(); tags[other]=nil end
    if spectating==other then restoreCamera() end
    refreshPlayers()
end)
local api = {}
api.Destroy = function()
    if not alive then return end
    alive=false
    for _,connection in ipairs(runtime.movementConnections or {}) do connection:Disconnect() end
    runtime.stopEmote(); runtime.stopRoleplay(); runtime.setShader(false)
    for _,connection in ipairs(runtime.quickConnections) do connection:Disconnect() end; table.clear(runtime.quickConnections)
    save(true)
    settings.lowEffects=false; features.applyPerformance()
    if runtime.performanceOwned.fps~=nil and type(setfpscap)=="function" then pcall(setfpscap,runtime.performanceOwned.fps) end
    state.fly=false; state.noclip=false; state.fullbright=false; state.shadows=false
    for _,con in ipairs(connections) do con:Disconnect() end
    for _,con in ipairs(rowConnections) do con:Disconnect() end
    stopFly(); restoreCollisions(); clearVisuals(); applyLighting(); restoreCamera(); stopAntiVC()
    for h,values in pairs(originals) do
        if h.Parent then
            if values.speedOwned then h.WalkSpeed=values.WalkSpeed end
            if values.jumpOwned then h.JumpPower=values.JumpPower; h.JumpHeight=values.JumpHeight end
        end
    end
    for camera,value in pairs(cameraOriginal) do if camera.Parent then camera.FieldOfView=value end end
    for _,clip in pairs(uiSounds) do clip:Destroy() end
    if runtime.brightnessOriginal~=nil and Lighting.Brightness==runtime.brightnessOwned then Lighting.Brightness=runtime.brightnessOriginal end
    sound:Destroy(); backdropBlur:Destroy(); gui:Destroy()
    if env.ISBMenu==api then env.ISBMenu=nil end
end
-- Extend with your own client actions; callback errors are caught by the UI.
api.AddAction = function(id, category, name, description, callback)
    assert(type(id)=="string" and type(name)=="string" and type(callback)=="function", "Ungültige Aktion")
    assert(table.find(navNames,category) and category~="Start" and category~="Musik" and category~="Einstellungen", "Bewegung, Spieler oder Darstellung verwenden")
    for _,action in ipairs(actions) do assert(action.id~=id,"Aktions-ID bereits vorhanden") end
    addAction(id,category,name,tostring(description or ""),"button",callback)
    render()
end
api.Notify=notify
env.ISBMenu=api
task.spawn(function()
    if Marketplace then
