function runtime.resolveServerRegion(peer)
    if runtime.regionRequest then return end
    local ip=tostring(peer or ""):match("(%d+%.%d+%.%d+%.%d+)")
    if not ip then return end
    local octets={}
    for octet in ip:gmatch("%d+") do table.insert(octets,tonumber(octet)) end
    if #octets~=4 then return end
    for _,octet in ipairs(octets) do if octet>255 then return end end
    local a,b=octets[1],octets[2]
    if a==0 or a==10 or a==127 or a>=224 or (a==169 and b==254) or (a==172 and b>=16 and b<=31) or (a==192 and b==168) or (a==100 and b>=64 and b<=127) then return end
    runtime.regionRequest=true
    task.spawn(function()
        -- Always specify the server peer. An empty GeoIP URL would locate us.
        local ok,data=pcall(requestJSON,"https://ipwho.is/"..ip.."?fields=success,ip,city,region,country,country_code")
        if not alive then return end
        if ok and type(data)=="table" and data.success==true and data.ip==ip then
            local city=tostring(data.city or data.region or "")
            local country=tostring(data.country_code or data.country or "")
            if city~="" or country~="" then runtime.serverRegion="Verbindung: "..city..(city~="" and country~="" and " · " or "")..country end
        end
        if not runtime.serverRegion then runtime.serverRegion="Verbindungsregion nicht abrufbar" end
    end)
end
function runtime.refreshServerRegion()
    for _,source in ipairs({workspace,game}) do
        for _,name in ipairs({"ServerRegion","ServerLocation","ServerCountry"}) do
            local ok,value=pcall(function() return source:GetAttribute(name) end)
            if ok and type(value)=="string" and value~="" then runtime.serverRegion="Server: "..value:sub(1,70); return end
        end
    end
    local network=optionalService("NetworkClient")
    if network then pcall(function() connect(network.ConnectionAccepted,runtime.resolveServerRegion) end) end
    local logs=optionalService("LogService")
    if logs then
        pcall(function()
            local history=logs:GetLogHistory()
            for i=#history,1,-1 do
                local message=tostring(history[i].message or "")
                local peer=message:match("Connection accepted from%s+([%d%.]+)") or message:match("UDMUX Address%s*=%s*([%d%.]+)") or message:match("serverId:%s*([%d%.]+)")
                if peer then runtime.resolveServerRegion(peer); break end
            end
        end)
    end
    if not runtime.regionRequest then runtime.serverRegion="Server meldet keine Region" end
end
runtime.refreshServerRegion()
save()
render()
window.GroupTransparency=1; motionScale.Scale=0.94; window.Visible=false
dock.GroupTransparency=1
-- The greeting shares the dock glass, followed by a staggered left-to-right reveal.
function runtime.startWelcomeIntro()
    runtime.welcomeActive=true
    local welcome=make("CanvasGroup",{Name="WelcomeCapsule",BackgroundColor3=dock.BackgroundColor3,
        AnchorPoint=dock.AnchorPoint,Position=dock.Position+UDim2.fromOffset(0,16),Size=dock.Size,
        GroupTransparency=1,ZIndex=30},host)
    round(welcome,28); runtime.glassSurface(welcome,28); stroke(welcome)
    local greeting=label(welcome,"Hey "..player.DisplayName,18,C.text,UDim2.fromOffset(22,17),UDim2.new(1,-44,0,24))
    greeting.TextTransparency=1; greeting.ZIndex=31
    local stages={}; local ordered={dockClock}
    for _,name in ipairs(navNames) do table.insert(ordered,navButtons[name]) end
    table.insert(ordered,profile)
    indicator.Visible=false
    for i,obj in ipairs(ordered) do
        local position=obj.Position
        -- CanvasGroup clips its render target even when ClipsDescendants is false.
        -- Reserve space for the full hover lift and scale during the reveal.
        local revealPosition=position+UDim2.fromOffset(-8,-8)
        local layer=make("CanvasGroup",{Name="WelcomeReveal_"..i,BackgroundTransparency=1,GroupTransparency=1,
            Position=revealPosition+UDim2.fromOffset(0,8),Size=obj.Size+UDim2.fromOffset(16,16),ClipsDescendants=false,ZIndex=obj.ZIndex or 1},dock)
        table.insert(stages,{obj=obj,layer=layer,position=position,revealPosition=revealPosition,active=obj.Active})
        obj.Parent=layer; obj.Position=UDim2.fromOffset(8,8); obj.Active=false
    end
    function runtime.finishWelcome(cancel)
        if not runtime.welcomeActive then return end
        runtime.welcomeActive=false
        for _,stage in ipairs(stages) do
            if stage.obj.Parent then stage.obj.Parent=dock; stage.obj.Position=stage.position; stage.obj.Active=stage.active end
            if stage.layer.Parent then stage.layer:Destroy() end
        end
        indicator.Visible=true; dock.GroupTransparency=0
        if welcome.Parent then welcome:Destroy() end
        if not cancel and dockVisible then setOpen(settings.autoOpen); notify(CONFIG.Name.." bereit • "..settings.key.." öffnet das Menü") end
    end
    animate(welcome,{GroupTransparency=0,Position=dock.Position}); animate(greeting,{TextTransparency=0})
    task.delay(settings.reducedMotion and 0 or 2.8,function()
        if not alive or not runtime.welcomeActive then return end
        animate(greeting,{TextTransparency=1}); animate(welcome,{GroupTransparency=1})
        if dockVisible then animate(dock,{GroupTransparency=0}) end
    end)
    for i,stage in ipairs(stages) do
        task.delay(settings.reducedMotion and 0 or (3.02+(i-1)*.15),function()
            if alive and runtime.welcomeActive and dockVisible then animate(stage.layer,{GroupTransparency=0,Position=stage.revealPosition}) end
        end)
    end
    task.delay(settings.reducedMotion and 0 or (3.02+(#stages-1)*.15+.32),function()
        if alive then runtime.finishWelcome(false) end
    end)
end
runtime.startWelcomeIntro()
return api
